import "server-only";
import { createReadStream } from "node:fs";
import { mkdir, readFile, rename, stat, unlink, writeFile } from "node:fs/promises";
import path from "node:path";
import { Readable } from "node:stream";
import { env } from "@/server/env";

/**
 * Private object storage. Keys are generated by the application (never taken
 * from user input) and files are only ever served through authenticated route
 * handlers — there are no public URLs.
 */
export interface Storage {
  put(key: string, data: Buffer, contentType: string): Promise<void>;
  get(key: string): Promise<Buffer>;
  stream(key: string): Promise<{ body: ReadableStream<Uint8Array>; size: number }>;
  copy(fromKey: string, toKey: string): Promise<void>;
  delete(key: string): Promise<void>;
}

const KEY_RE = /^[a-z0-9][a-z0-9/_\-.]{2,200}$/;
function assertKey(key: string) {
  if (!KEY_RE.test(key) || key.includes("..")) throw new Error(`Invalid storage key: ${key}`);
}

class LocalStorage implements Storage {
  private root = path.resolve(env.STORAGE_LOCAL_DIR);
  private file(key: string) {
    assertKey(key);
    const p = path.resolve(this.root, key);
    if (!p.startsWith(this.root + path.sep)) throw new Error("Path traversal blocked");
    return p;
  }
  async put(key: string, data: Buffer) {
    const p = this.file(key);
    await mkdir(path.dirname(p), { recursive: true });
    const tmp = `${p}.${process.pid}.tmp`;
    await writeFile(tmp, data, { flag: "wx" });
    await rename(tmp, p);
  }
  async get(key: string) {
    return readFile(this.file(key));
  }
  async stream(key: string) {
    const p = this.file(key);
    const { size } = await stat(p);
    return { body: Readable.toWeb(createReadStream(p)) as ReadableStream<Uint8Array>, size };
  }
  async copy(fromKey: string, toKey: string) {
    await this.put(toKey, await this.get(fromKey));
  }
  async delete(key: string) {
    await unlink(this.file(key)).catch(() => {});
  }
}

class S3Storage implements Storage {
  private clientPromise = (async () => {
    const { S3Client } = await import("@aws-sdk/client-s3");
    if (!env.S3_BUCKET) throw new Error("S3_BUCKET is required when STORAGE_DRIVER=s3");
    return new S3Client({
      region: env.S3_REGION ?? "auto",
      endpoint: env.S3_ENDPOINT || undefined,
      forcePathStyle: env.S3_FORCE_PATH_STYLE,
      credentials:
        env.S3_ACCESS_KEY_ID && env.S3_SECRET_ACCESS_KEY
          ? { accessKeyId: env.S3_ACCESS_KEY_ID, secretAccessKey: env.S3_SECRET_ACCESS_KEY }
          : undefined,
    });
  })();
  private bucket = env.S3_BUCKET!;

  async put(key: string, data: Buffer, contentType: string) {
    assertKey(key);
    const { PutObjectCommand } = await import("@aws-sdk/client-s3");
    await (await this.clientPromise).send(
      new PutObjectCommand({ Bucket: this.bucket, Key: key, Body: data, ContentType: contentType }),
    );
  }
  async get(key: string) {
    assertKey(key);
    const { GetObjectCommand } = await import("@aws-sdk/client-s3");
    const res = await (await this.clientPromise).send(new GetObjectCommand({ Bucket: this.bucket, Key: key }));
    return Buffer.from(await res.Body!.transformToByteArray());
  }
  async stream(key: string) {
    assertKey(key);
    const { GetObjectCommand } = await import("@aws-sdk/client-s3");
    const res = await (await this.clientPromise).send(new GetObjectCommand({ Bucket: this.bucket, Key: key }));
    return { body: res.Body!.transformToWebStream() as ReadableStream<Uint8Array>, size: res.ContentLength ?? 0 };
  }
  async copy(fromKey: string, toKey: string) {
    assertKey(fromKey);
    assertKey(toKey);
    const { CopyObjectCommand } = await import("@aws-sdk/client-s3");
    await (await this.clientPromise).send(
      new CopyObjectCommand({ Bucket: this.bucket, Key: toKey, CopySource: `${this.bucket}/${fromKey}` }),
    );
  }
  async delete(key: string) {
    assertKey(key);
    const { DeleteObjectCommand } = await import("@aws-sdk/client-s3");
    await (await this.clientPromise).send(new DeleteObjectCommand({ Bucket: this.bucket, Key: key }));
  }
}

declare global {
  var __nskStorage: Storage | undefined;
}

export const storage: Storage =
  globalThis.__nskStorage ?? (globalThis.__nskStorage = env.STORAGE_DRIVER === "s3" ? new S3Storage() : new LocalStorage());

export function newKey(prefix: "revisions" | "uploads" | "assets", ext: string) {
  const d = new Date();
  const ym = `${d.getUTCFullYear()}/${String(d.getUTCMonth() + 1).padStart(2, "0")}`;
  return `${prefix}/${ym}/${crypto.randomUUID()}.${ext}`;
}
